ARY schema_name=BINARY DATABASE())) OR (BINARY trigger_name='vq_command_bi' AND BINARY event_object_table='visit_question_command' AND BINARY event_object_schema=BINARY DATABASE() AND action_timing='BEFORE' AND event_manipulation='INSERT' AND action_orientation='ROW' AND SHA2(action_statement,256)='c4596dd732d715bc98e7ea2350c2b8d6c61b3c6da07cf0fe4f5847f9888bf8b7' AND sql_mode='STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' AND character_set_client='utf8mb4' AND collation_connection='utf8mb4_bin' AND database_collation=(SELECT default_collation_name FROM information_schema.schemata WHERE BINARY schema_name=BINARY DATABASE())) OR (BINARY trigger_name='vq_command_bu' AND BINARY event_object_table='visit_question_command' AND BINARY event_object_schema=BINARY DATABASE() AND action_timing='BEFORE' AND event_manipulation='UPDATE' AND action_orientation='ROW' AND SHA2(action_statement,256)='286156cb36a40f5a101ed1d31e0e89ee1bfd1faf40b32d64b56df01ac1b47a2a' AND sql_mode='STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' AND character_set_client='utf8mb4' AND collation_connection='utf8mb4_bin' AND database_collation=(SELECT default_collation_name FROM information_schema.schemata WHERE BINARY schema_name=BINARY DATABASE())) OR (BINARY trigger_name='vq_command_bd' AND BINARY event_object_table='visit_question_command' AND BINARY event_object_schema=BINARY DATABASE() AND action_timing='BEFORE' AND event_manipulation='DELETE' AND action_orientation='ROW' AND SHA2(action_statement,256)='1dd7ca749ba3648757fe99047be61cd24e030bb08ad74878c2f975755b9eb0ec' AND sql_mode='STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' AND character_set_client='utf8mb4' AND collation_connection='utf8mb4_bin' AND database_collation=(SELECT default_collation_name FROM information_schema.schemata WHERE BINARY schema_name=BINARY DATABASE())) THEN 1 ELSE 0 END)=9 FROM information_schema.triggers WHERE BINARY trigger_schema=BINARY DATABASE() AND (event_object_table IN ('visit_question_state','visit_question_event','visit_question_command') OR LEFT(trigger_name,3)='vq_'))
