  AND NOT EXISTS(SELECT 1 FROM information_schema.table_constraints WHERE BINARY constraint_schema=BINARY DATABASE() AND LEFT(constraint_name,3)='vq_' AND table_name NOT IN ('visit_question_state','visit_question_event','visit_question_command'))
THEN 1 ELSE 0 END AS compatible;
-- 未选库时 present=NULL，必须 STOP，不能解释为 ABSENT。
-- 01 判定：present=0 且 B=READY、environment compatible=1 才是 ABSENT；metadata compatible 在完全缺失时为 0。
-- present>0 时只有 exact metadata compatible=1 才是 PRESENT；其他情况 STOP，禁止执行 02。
-- PRESENT 必须转到 03 完成行完整性检查，不执行或重复任何 DDL。
